input.command:
awk '
  /^id: MONDO:/ {id=$2; has_venom=0; venom_code=""; has_subset=0; subset_venom=""}
  /xref: VeNom:/ {has_venom=1; match($0, /VeNom:([0-9]+)/, a); venom_code=a[1]}
  /subset: venom_/ {has_subset=1; match($0, /VeNom:([0-9]+)/, b); subset_venom=b[1]}
  /^$/ {
    if (has_venom && venom_code != "" && (!has_subset || subset_venom != venom_code)) {
      print id " has VeNom:" venom_code " but subset source is " subset_venom
    }
    has_venom=0; venom_code=""; has_subset=0; subset_venom=""
  }
' src/ontology/mondo-edit.obo | head -20

